    case "control_updated": self = .controlUpdated(try ControlUpdatedEvent(from: decoder))
    case "prompt_handled": self = .promptHandled(try PromptHandledEvent(from: decoder))
    case "model_updated": self = .modelUpdated(try ModelUpdatedEvent(from: decoder))
    case "fast_updated": self = .fastUpdated(try FastUpdatedEvent(from: decoder))
    case "metrics_updated": self = .metricsUpdated(try MetricsUpdatedEvent(from: decoder))
